module.exports = function (data) {
  function version(reply) {
    var value = reply && reply.status === 200 && reply.data && reply.data.version;
    return typeof value === 'string' && /^[A-Za-z0-9._-]{1,80}$/.test(value) ? value : null;
  }
  var context = data.publish_context;
  var before = version(data.version_before);
  var after = version(data.version_after);
  var subject;
  var observation;
  if (before === null || after === null) {
    var missing = [];
    if (before === null) missing.push('before Publish');
    if (after === null) missing.push('after the wait');
    subject = 'Publish site: could not verify';
    observation = 'Could not read a valid public build version ' + missing.join(' and ') + '. The update status is unknown.';
  } else if (before !== after) {
    subject = 'Publish site: updated';
    observation = 'Public build changed from ' + before + ' to ' + after + '.';
  } else {
    subject = 'Publish site: not updated';
    observation = 'Public build is still ' + before + ' after about 10 minutes. The build may still be running; this does not prove a deployment failed.';
  }
  return {
    subject: subject,
    message: 'Request ' + context.requestId + ' at ' + context.hookRespondedAt + '. ' + observation + ' This checks the public site during this request window; overlapping Publishes or other deployments cannot be attributed to a particular press. [Open Vercel](https://vercel.com/dashboard).'
  };
};

